// Você poderá usar vários salários Tarefa diferentes.
// Para isto crie os eventos alterando apenas
// a variável SalarioTarefa1 para o respectivo Salário Tarefa.
// A variável SalarioTarefa1 aceita alteração mesmo quando for mais que 10
// salários tarefa.
// Exemplos: SalarioTarefa11, SalarioTarefa12, SalarioTarefa13, etc.

Se EscopoSalario ou EscopoSalarioCompl ou EscopoRescisao ou EscopoRescisaoCompl Entao
Se Tarefeiro Entao
   Resultado=(ParamValorRef*SalarioTarefa1)-ValorEventoOrigem
   BaseSalarioTarefeiro=BaseSalarioTarefeiro+Resultado
   ValorSalarioPago=ValorSalarioPago+Resultado
   Salario=ValorSalarioPago
   ValorRemuneracao=ValorRemuneracao+Salario
   RemuneracaoIntegral=RemuneracaoIntegral+Resultado
 Fim
Fim

// Você poderá usar vários salários Aula diferentes.
// Para isto crie os eventos alterando apenas
// a variável  SalarioAula1 para o respectivo Salário Aula.
// A variável SalarioAula1 aceita alteração mesmo quando for mais que 10
// salários aula.
// Exemplos: SalarioAula11, SalarioAula12, SalarioAula13, etc

Se EscopoSalario ou EscopoSalarioCompl ou EscopoRescisao ou EscopoRescisaoCompl Entao
Se DocenteAulista Entao
   Resultado=(ParamValorRef*SalarioAula1)-ValorEventoOrigem
   BaseSalarioAulista=BaseSalarioAulista+Resultado
   ValorSalarioPago=ValorSalarioPago+Resultado
   Salario=ValorSalarioPago
   ValorRemuneracao=ValorRemuneracao+Salario
   RemuneracaoIntegral=RemuneracaoIntegral+Resultado
 Fim
Fim

Se ReciboUmTercoFeriasMP927= 1 Entao
   Retornar
Senao
	// Qdo em EscopoFerias , o que estiver entre o comando
	// Se e o Fim , será considerado apenas no cálculo
	// de férias
	Se EscopoFerias ou EscopoFeriasDom Entao

	   // Define o tipo de rateio que será usado nos
	   // cálculos proporcionais nos meses abrangidos
	   // pelas férias. Neste caso será usado o rateio
	   // para abono de férias
	   RateioEmUsoNesteEventoFerias=RateioFeriasAbono

	   // Para os Mensalistas, comissionados e Tarefeiros
	   Se Mensalista Ou Horista ou Comissionado Ou Tarefeiro ou DocenteMensalista ou DocenteAulista Entao

		  // Atribui para à Global Resultado a Variáveis do
		  // ValorAbonoPecuniarioPago e faz
		  // a divisão por três
		  Resultado=ValorAbonoPecuniarioPago/3

		  // Atribui valor do abono à global
		  // ValorUmTercoDeAbonoPecuniario para posterior
		  // envio deste valor para a Folha de Pagamento
		  ValorUmTercoDeAbonoPecuniario=Resultado
	   Fim

	   // Para Horistas
	   Se Horista Entao
		  // Atribui para à Global Resultado a soma do
		  // Salario com as médias de variáveis e faz
		  // a divisão por três

		   Resultado=ValorAbonoPecuniarioPago/3
		  // Faz o rateio mes-a-mes conforme os meses
		  // abrangidos pelas férias

		  // Atribui valor do abono à global
		  // ValorUmTercoDeAbonoPecuniario para posterior
		  // envio deste valor para a Folha de Pagamento
		  ValorUmTercoDeAbonoPecuniario=Resultado
	   Fim
	   // Não Incidência de IRRF para Funcionários que iniciaram Férias
	   // a partir do dia 06/05/2009, conforme Art. 1 da IN/RBF 936/2009.
	   Se PagaUmTercoFeriasMP927=0   Entao
		   ValorUmTercoDeAbonoMP927 = round(ValorUmTercoDeAbonoPecuniario)
		   ValorUmTercoDeAbonoPecuniario = 0
		   Resultado = 0
	   Fim

	   Se (DiaPagamentoFerias>=06 e MesPagamentoFerias=05 e AnoPagamentoFerias=2009) ou (MesPagamentoFerias>05 e AnoPagamentoFerias=2009) ou (AnoPagamentoFerias>2009) Entao
		  BaseIrrfFerias=BaseIrrfFerias-Resultado
	   Fim
	Fim

	 // Alteração realizada em virtude da Solução de Consulta COSIT Nº 209 DE 16/12/2021
    Se (DiaPagamentoFerias>=13 e MesPagamentoFerias=01 e AnoPagamentoFerias=2022) ou (MesPagamentoFerias>01 e AnoPagamentoFerias=2022) ou (AnoPagamentoFerias>2022) Entao
       BaseIrrfFerias = BaseIrrfFerias + Resultado
       Temp30=10000
    Fim
	Fim

	// Qdo em EscopoFerias , o que estiver entre o comando
	// Se e o Fim , será considerado apenas no cálculo
	// de férias

	// Qdo em EscopoRescisao , o que estiver entre o comando
	// Se e o Fim , será considerado apenas no cálculo
	// de férias

	Se EscopoSalario ou EscopoSalarioDom ou EscopoRescisao ou EscopoRescisaodom Entao
   ExecutaEmAfastGrupo1 = Verdadeiro
   ExecutaEmAfastGrupo2 = Verdadeiro

	   Se ParamValorRef<>0 Entao
		  Resultado=ParamValorRef
		  ParamValorRef=0
	   Senao
		  Se EstaNoPrimeiroMesDeFerias Entao
			 Se EscopoSalario ou EscopoSalarioDom Entao
				// Apura o valor do Um terço de Abono proporcional
				// do mês corrente, através do valor previamente
				// gravado em Escopo Férias
				Resultado=(ValorUmTercoDeAbonoPecuniario*RateioDeAbonoNoMes)
			 Senao
				Resultado=(ValorUmTercoDeAbonoPecuniario*RateioFeriasEspecial)
			 Fim
		  Fim
	   Fim

	   // Não Incidência de IRRF para Funcionários que iniciaram Férias
	   // a partir do dia 06/05/2009, conforme Art. 1 da IN/RBF 936/2009.

	   Se (DataCompetenciaMes>=05 e DataCompetenciaAno=2009) ou (DataCompetenciaAno>2009) Entao
		    BaseIrrfFerias=BaseIrrfFerias-Resultado
	   Fim
    // Alteração realizada em virtude da Solução de Consulta COSIT Nº 209 DE 16/12/2021
    Se (DiaPagamentoFerias>=13 e MesPagamentoFerias=01 e AnoPagamentoFerias=2022) ou (MesPagamentoFerias>01 e AnoPagamentoFerias=2022) ou (AnoPagamentoFerias>2022) Entao
       BaseIrrfFerias = BaseIrrfFerias + Resultado
       Temp30=10000
    Fim

Fim

